async function watermarkedPreview(url:string){const image=await new Promise<HTMLImageElement>((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=()=>reject(new Error('Could not create a catalogue preview.'));i.src=url});const canvas=document.createElement('canvas');canvas.width=900;canvas.height=900;const ctx=canvas.getContext('2d')!;const scale=Math.min(730/image.width,730/image.height);ctx.drawImage(image,(900-image.width*scale)/2,(900-image.height*scale)/2,image.width*scale,image.height*scale);ctx.save();ctx.globalCompositeOperation='source-atop';ctx.translate(450,450);ctx.rotate(-Math.PI/6);ctx.fillStyle='rgba(40,59,39,.28)';ctx.font='bold 34px sans-serif';ctx.textAlign='center';for(let y=-600;y<700;y+=160)for(let x=-600;x<700;x+=330)ctx.fillText('PRINTWEAR • PREVIEW',x,y);ctx.restore();return await new Promise<Blob>((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Preview export failed.')),'image/png'))}
