 {tab==='catalogue'&&batchReviewMode&&<section className="admin-card"><div className="section-heading"><div><h2>Your artwork catalogue.</h2><p className="muted" style={{fontSize:11}}>Draft → inspect → approve → storefront.</p></div><button className="button primary" onClick={()=>changeTab('prep')}>Prepare artwork <ImagePlus size={16}/></button></div><div className="category-tabs" role="group" aria-label="Browse approved artwork categories">{categories.map(c=><button key={c} className={catalogueCategory===c?'active':''} onClick={()=>setCatalogueCategory(c)}>{c}</button>)}</div>{catalogueCategory!=='All artwork'&&<p className="notice">Showing artwork approved for {catalogueCategory}. Drafts are visible only in your studio.</p>}<div className="batch-approval-controls"><div><strong>{batchReviewIds.length?'Prompt to Print batch review':'Group approval'}</strong><p>Review the selected originals, AI descriptions, prices and categories. Approving confirms your review and ownership. Failed checks stay as drafts; low DPI remains a warning.</p></div><div className="form-actions"><button className="button secondary" disabled={busy} onClick={()=>setApprovalIds(catalogue.filter(p=>p.status==='draft').slice(0,20).map(p=>p.id))}>Select up to 20 drafts</button><button className="button secondary" disabled={busy||!approvalIds.length} onClick={()=>setApprovalIds([])}>Clear selection</button><button className="button primary" disabled={busy||!approvalIds.some(id=>catalogue.some(p=>p.id===id&&p.status==='draft'))} onClick={()=>action(async()=>{const selected=catalogue.filter(p=>approvalIds.includes(p.id)&&p.status==='draft');const results=await approveDraftBatch(selected,categories,api,(done,total,title)=>setProgress(`Approving ${done}/${total}: ${title}`));const failed=results.filter(r=>!r.ok);setApprovalIds(failed.map(r=>r.id));await refresh();setMessage(`${results.length-failed.length}/${results.length} designs approved and saved to their categories.`);if(failed.length)setError(failed.map(r=>`${catalogue.find(p=>p.id===r.id)?.title||r.id}: ${r.error}`).join('\n'))})}>Approve selected ({catalogue.filter(p=>approvalIds.includes(p.id)&&p.status==='draft').length}) <CheckCircle2 size={16}/></button></div><p className="version-footnote">Keep this tab open during group approval. Completed approvals are saved individually; you can resume the remaining drafts after a refresh.</p>{batchReviewIds.length>0&&<a className="text-link" href="/admin">View all catalogue artwork</a>}</div>{catalogue.filter(p=>catalogueCategory==='All artwork'||(p.metadata_json&&JSON.parse(p.metadata_json).approvedCategories?.includes(catalogueCategory))||p.status==='published'&&p.category===catalogueCategory).length?<div className="table-wrap"><table className="catalogue-table"><thead><tr><th>Select</th><th>Artwork</th><th>Format</th><th>Price</th><th>Status</th><th>Review</th></tr></thead><tbody>{catalogue.filter(p=>catalogueCategory==='All artwork'||(p.metadata_json&&JSON.parse(p.metadata_json).approvedCategories?.includes(catalogueCategory))||p.status==='published'&&p.category===catalogueCategory).map(p=><tr key={p.id}><td><input type="checkbox" aria-label={`Select ${p.title} for group approval`} disabled={busy||p.status!=='draft'||!approvalIds.includes(p.id)&&approvalIds.length>=20} checked={approvalIds.includes(p.id)&&p.status==='draft'} onChange={e=>setApprovalIds(current=>e.target.checked?[...new Set([...current,p.id])]:current.filter(id=>id!==p.id))}/></td><td>{(p.preview_front||p.preview_back)&&<button className="category-thumbnail" aria-label={`View ${p.title}`} onClick={()=>reviewProduct(p.id)}><img src={`/api/assets/${p.preview_front||p.preview_back}`} alt={p.title}/></button>}{p.title}{p.description&&<p className="batch-description">{p.description}</p>}<small className="muted" style={{display:'block',marginTop:6}}>{p.metadata_json?JSON.parse(p.metadata_json).approvedCategories?.join(' · ')||`${p.category} · category approval pending`:p.category}</small></td><td>{p.type==='pair'?'Front + back':p.type}</td><td>{money(p.price_cents)}</td><td><span className={`quality-tag ${p.status==='published'?'pass':''}`}>{p.status.toUpperCase()}</span>{p.quality==='approved_low_dpi'&&<small className="low-dpi-note">LOW DPI · OWNER APPROVED</small>}</td><td><button className="text-link" disabled={busy} onClick={()=>reviewProduct(p.id)}>Open review <ArrowUpRight size={13}/></button></td></tr>)}</tbody></table></div>:<div className="table-empty"><Images size={34}/><h3 style={{margin:'15px 0'}}>{catalogueCategory==='All artwork'?'Your first originals start here.':'No approved artwork in this category yet.'}</h3><p>Approve category checkboxes in an artwork review to file it here.</p></div>}</section>}
